TRACK_BASE_Z = float(PLATFORM_SETTINGS.get('top_z_m', 0.0)) if PLATFORM_ENABLED else 0.0
ACTOR_HANDLES = {}
NEXT_COMPOSITE_BASIC_SHAPE_ACTOR_NUMBER = 5000
