def project_scale():
    return float(TRACK_DATA.get('project', {}).get('scale_factor', 1.0))

def editor_yaw_to_qlabs_radians(editor_rotation_deg):
    return math.radians(-float(editor_rotation_deg))

def actor_effective_scale(obj):
    multiplier = max(0.001, float(obj.get('actor_scale', 1.0)))
    if bool(obj.get('scale_with_project', True)):
        multiplier *= project_scale()
    return multiplier

def actor_location(obj, extra_z=0.0):
    scale = project_scale()
    return [float(obj.get('x', 0.0)) * scale, float(obj.get('y', 0.0)) * scale, TRACK_BASE_Z + float(obj.get('z_m', 0.0)) * scale + extra_z]

def _register_actor_handle(obj, actor):
    """Expose an actor by both stable object id and readable identifier."""
    object_id = str(obj.get('id', ''))
    identifier = str(obj.get('identifier', ''))
    if object_id:
        ACTOR_HANDLES[object_id] = actor
    if identifier:
        ACTOR_HANDLES[identifier] = actor

def _asg_yaw(obj):
    return editor_yaw_to_qlabs_radians(obj.get('rotation_deg', 0.0))

def _asg_scale(obj):
    return actor_effective_scale(obj)

def _asg_base(obj):
    return [float(obj.get('x', 0.0)) * project_scale(), float(obj.get('y', 0.0)) * project_scale(), TRACK_BASE_Z + float(obj.get('z_m', 0.0)) * project_scale()]

def _asg_tangent(obj):
    yaw = _asg_yaw(obj)
    return [math.cos(yaw), math.sin(yaw), 0.0]

def _asg_left_axis(obj):
    yaw = _asg_yaw(obj)
    return [math.sin(yaw), -math.cos(yaw), 0.0]

def _asg_world(obj, lateral=0.0, z=0.0, front=0.0):
    """Map sign-local coordinates to world coordinates.

    lateral: +left on the sign face
    z:       height above the item's base
    front:   +toward the approaching driver / visible sign face (-tangent)
    """
    base = _asg_base(obj)
    scale = _asg_scale(obj)
    t = _asg_tangent(obj)
    n = _asg_left_axis(obj)
    return [base[0] + n[0] * lateral * scale - t[0] * front * scale, base[1] + n[1] * lateral * scale - t[1] * front * scale, base[2] + z * scale]

def _asg_spawn_shape_world(qlabs, obj, location, rotation, dimensions, configuration, color, roughness=0.25, collisions=False):
    actor = QLabsBasicShape(qlabs)
    scale = _asg_scale(obj)
    actor.spawn(location=[float(v) for v in location], rotation=[float(v) for v in rotation], scale=[max(0.001, float(v) * scale) for v in dimensions], configuration=configuration, waitForConfirmation=True)
    actor.set_material_properties(color=list(color), roughness=float(roughness), metallic=False, waitForConfirmation=True)
    actor.set_enable_dynamics(False, waitForConfirmation=True)
    actor.set_enable_collisions(bool(collisions), waitForConfirmation=True)
    return actor

def _asg_spawn_cube(qlabs, obj, lateral, z, front, dimensions, color, rotation=None, roughness=0.25, collisions=False):
    if rotation is None:
        rotation = [0.0, 0.0, _asg_yaw(obj)]
    return _asg_spawn_shape_world(qlabs, obj, _asg_world(obj, lateral, z, front), rotation, dimensions, QLabsBasicShape.SHAPE_CUBE, color, roughness=roughness, collisions=collisions)

def _asg_spawn_disc(qlabs, obj, diameter, color, z=2.45, front=0.0, depth=0.08):
    return _asg_spawn_shape_world(qlabs, obj, _asg_world(obj, 0.0, z, front), [0.0, math.pi / 2.0, _asg_yaw(obj)], [diameter, diameter, depth], QLabsBasicShape.SHAPE_CYLINDER, color, roughness=0.22, collisions=False)

def _asg_cross(a, b):
    return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]

def _asg_matrix_to_euler_zyx(matrix):
    r00, r01, r02 = matrix[0]
    r10, r11, r12 = matrix[1]
    r20, r21, r22 = matrix[2]
    if abs(r20) < 1.0 - 1e-08:
        pitch = -math.asin(r20)
        roll = math.atan2(r21, r22)
        yaw = math.atan2(r10, r00)
    else:
        pitch = -math.copysign(math.pi / 2.0, r20)
        roll = 0.0
        yaw = math.atan2(-r01, r11)
    return [roll, pitch, yaw]

def _asg_segment_rotation(obj, p1, p2, coord_scale=1.0):
    du = (float(p2[0]) - float(p1[0])) * coord_scale
    dv = (float(p2[1]) - float(p1[1])) * coord_scale
    length = math.hypot(du, dv)
    if length <= 1e-09:
        return None
    n = _asg_left_axis(obj)
    t = _asg_tangent(obj)
    face_normal = [-t[0], -t[1], 0.0]
    x_axis = [n[0] * du / length, n[1] * du / length, dv / length]
    y_axis = face_normal
    z_axis = _asg_cross(x_axis, y_axis)
    return _asg_matrix_to_euler_zyx([[x_axis[0], y_axis[0], z_axis[0]], [x_axis[1], y_axis[1], z_axis[1]], [x_axis[2], y_axis[2], z_axis[2]]])

def _asg_spawn_segment(qlabs, obj, p1, p2, width, depth, color, face_z=2.45, front=0.055, coord_scale=1.0, overlap=1.08, roughness=0.12):
    du = (float(p2[0]) - float(p1[0])) * coord_scale
    dv = (float(p2[1]) - float(p1[1])) * coord_scale
    length = math.hypot(du, dv)
    if length <= 1e-09:
        return None
    midpoint = ((float(p1[0]) + float(p2[0])) / 2.0 * coord_scale, (float(p1[1]) + float(p2[1])) / 2.0 * coord_scale)
    location = _asg_world(obj, midpoint[0], face_z + midpoint[1], front)
    return _asg_spawn_shape_world(qlabs, obj, location, _asg_segment_rotation(obj, p1, p2, coord_scale=coord_scale), [length * overlap, depth, width], QLabsBasicShape.SHAPE_CUBE, color, roughness=roughness, collisions=False)

def _asg_polyline(qlabs, obj, points, width, depth, color, face_z=2.45, front=0.055, coord_scale=1.0, subdivisions=1, overlap=1.08):
    if len(points) < 2:
        return
    for index in range(len(points) - 1):
        p1 = points[index]
        p2 = points[index + 1]
        steps = max(1, int(subdivisions))
        previous = p1
        for step in range(1, steps + 1):
            f = step / steps
            current = (p1[0] + (p2[0] - p1[0]) * f, p1[1] + (p2[1] - p1[1]) * f)
            _asg_spawn_segment(qlabs, obj, previous, current, width, depth, color, face_z=face_z, front=front, coord_scale=coord_scale, overlap=overlap)
            previous = current

def _asg_arc_points(cx, cz, radius, start_deg, end_deg, segments):
    points = []
    for index in range(segments + 1):
        f = index / segments
        angle = math.radians(start_deg + (end_deg - start_deg) * f)
        points.append((cx + radius * math.cos(angle), cz + radius * math.sin(angle)))
    return points

def _asg_filled_triangle(qlabs, obj, tip, back_a, back_b, width, depth, color, face_z=2.45, front=0.055, coord_scale=1.0, layers=14):
    layers = max(2, int(layers))
    for index in range(layers):
        f = (index + 0.5) / layers
        a = (back_a[0] + (tip[0] - back_a[0]) * f, back_a[1] + (tip[1] - back_a[1]) * f)
        b = (back_b[0] + (tip[0] - back_b[0]) * f, back_b[1] + (tip[1] - back_b[1]) * f)
        _asg_spawn_segment(qlabs, obj, a, b, width * 1.05, depth, color, face_z=face_z, front=front, coord_scale=coord_scale, overlap=1.08)

def _asg_arrow_head(qlabs, obj, tip, back_a, back_b, width, depth, color, face_z=2.45, front=0.055, coord_scale=1.0, layers=14):
    _asg_filled_triangle(qlabs, obj, tip, back_a, back_b, width, depth, color, face_z=face_z, front=front, coord_scale=coord_scale, layers=layers)
    _asg_polyline(qlabs, obj, [back_a, tip], width, depth, color, face_z=face_z, front=front, coord_scale=coord_scale, subdivisions=6)
    _asg_polyline(qlabs, obj, [back_b, tip], width, depth, color, face_z=face_z, front=front, coord_scale=coord_scale, subdivisions=6)

def _asg_face_box(qlabs, obj, center_x, center_z, size_x, size_z, depth, color, face_z=2.45, front=0.055, roughness=0.16):
    return _asg_spawn_shape_world(qlabs, obj, _asg_world(obj, center_x, face_z + center_z, front), [0.0, math.pi / 2.0, _asg_yaw(obj)], [size_x, size_z, depth], QLabsBasicShape.SHAPE_CUBE, color, roughness=roughness, collisions=False)

def _asg_face_disc(qlabs, obj, center_x, center_z, diameter, depth, color, face_z=2.45, front=0.055):
    return _asg_spawn_shape_world(qlabs, obj, _asg_world(obj, center_x, face_z + center_z, front), [0.0, math.pi / 2.0, _asg_yaw(obj)], [diameter, diameter, depth], QLabsBasicShape.SHAPE_CYLINDER, color, roughness=0.16, collisions=False)

def _asg_rotated_square(qlabs, obj, center_point, side, angle_deg, depth, color, face_z=2.45, front=0.055):
    angle = math.radians(angle_deg)
    half = side / 2.0
    dx = math.cos(angle) * half
    dz = math.sin(angle) * half
    p1 = (center_point[0] - dx, center_point[1] - dz)
    p2 = (center_point[0] + dx, center_point[1] + dz)
    return _asg_spawn_shape_world(qlabs, obj, _asg_world(obj, center_point[0], face_z + center_point[1], front), _asg_segment_rotation(obj, p1, p2), [side, depth, side], QLabsBasicShape.SHAPE_CUBE, color, roughness=0.14, collisions=False)

def _asg_pole(qlabs, obj, height=2.3, width=0.08, back=0.1):
    return _asg_spawn_cube(qlabs, obj, 0.0, height / 2.0, -back, [width, width, height], [0.55, 0.55, 0.57], rotation=[0.0, 0.0, _asg_yaw(obj)], roughness=0.75, collisions=True)

def _asg_warning_triangle(qlabs, obj, half_width=0.62, bottom_z=-0.52, top_z=0.58, rows=42, border_width=0.095, face_z=2.45, front=0.055):
    white = [0.98, 0.98, 0.98]
    red = [0.92, 0.06, 0.06]
    total_height = top_z - bottom_z
    row_height = total_height / rows * 1.18
    for index in range(rows):
        f = (index + 0.5) / rows
        z = bottom_z + total_height * f
        hw = half_width * (1.0 - f)
        _asg_spawn_segment(qlabs, obj, (-hw, z), (hw, z), row_height, 0.035, white, face_z=face_z, front=front, overlap=1.04)
    apex = (0.0, top_z)
    left = (-half_width, bottom_z)
    right = (half_width, bottom_z)
    for p1, p2 in ((left, apex), (apex, right), (right, left)):
        _asg_spawn_segment(qlabs, obj, p1, p2, border_width, 0.033, red, face_z=face_z, front=front + 0.012, overlap=1.02)

def _asg_spawn_front_or_side(qlabs, obj, left=False):
    white = [0.98, 0.98, 0.98]
    blue = [0.06, 0.36, 0.78]
    _asg_pole(qlabs, obj, 2.3, 0.08, 0.1)
    _asg_spawn_disc(qlabs, obj, 1.2, blue, z=2.45, front=0.0, depth=0.08)
    cs = 0.92
    width = 0.055 * cs
    stem = [(0.0, -0.34), (0.0, -0.22), (0.0, -0.1), (0.0, 0.02), (0.0, 0.14), (0.0, 0.26), (0.0, 0.34)]
    _asg_polyline(qlabs, obj, stem, width, 0.025, white, front=0.06, coord_scale=cs)
    _asg_arrow_head(qlabs, obj, (0.0, 0.46), (-0.13, 0.31), (0.13, 0.31), width, 0.025, white, front=0.06, coord_scale=cs)
    mirror = -1.0 if left else 1.0
    arc = _asg_arc_points(0.22, -0.03, 0.22, 180.0, 90.0, 20)
    arc = [(mirror * x, z) for x, z in arc]
    _asg_polyline(qlabs, obj, arc, width, 0.025, white, front=0.06, coord_scale=cs)
    arc_end = arc[-1]
    branch_end = (mirror * 0.42, 0.19)
    _asg_polyline(qlabs, obj, [arc_end, branch_end], width, 0.025, white, front=0.06, coord_scale=cs, subdivisions=4)
    _asg_arrow_head(qlabs, obj, (mirror * 0.54, 0.19), (mirror * 0.39, 0.32), (mirror * 0.39, 0.06), width, 0.025, white, front=0.06, coord_scale=cs)

def _asg_spawn_turn_warning(qlabs, obj, left=False):
    black = [0.04, 0.04, 0.04]
    _asg_pole(qlabs, obj, 2.25, 0.08, 0.11)
    _asg_warning_triangle(qlabs, obj)
    mirror = -1.0 if left else 1.0

    def m(p):
        return (mirror * p[0], p[1])
    stem = [m((-0.12, -0.28)), m((-0.12, -0.18)), m((-0.12, -0.08)), m((-0.12, 0.02))]
    _asg_polyline(qlabs, obj, stem, 0.095, 0.028, black, front=0.083)
    curve = _asg_arc_points(0.04, 0.02, 0.16, 180.0, 115.0, 20)
    curve = [m(p) for p in curve]
    _asg_polyline(qlabs, obj, curve, 0.095, 0.028, black, front=0.083)
    a = curve[-2]
    b = curve[-1]
    dx = b[0] - a[0]
    dz = b[1] - a[1]
    length = math.hypot(dx, dz)
    dx /= length
    dz /= length
    branch_end = (b[0] + dx * 0.095, b[1] + dz * 0.095)
    _asg_polyline(qlabs, obj, [b, branch_end], 0.095, 0.028, black, front=0.083, subdivisions=5)
    branch_angle = math.degrees(math.atan2(dz, dx))
    _asg_rotated_square(qlabs, obj, branch_end, 0.07, branch_angle - 45.0, 0.028, black, front=0.085)

def _asg_spawn_u_turn(qlabs, obj, prohibited=False):
    white = [0.98, 0.98, 0.98]
    blue = [0.06, 0.36, 0.78]
    red = [0.82, 0.08, 0.08]
    black = [0.08, 0.08, 0.08]
    _asg_pole(qlabs, obj, 2.3, 0.08, 0.1)
    if prohibited:
        _asg_spawn_disc(qlabs, obj, 1.22, red, z=2.45, depth=0.08)
        _asg_spawn_disc(qlabs, obj, 0.96, white, z=2.45, front=0.012, depth=0.0656)
        color = black
        front = 0.05
    else:
        _asg_spawn_disc(qlabs, obj, 1.2, blue, z=2.45, depth=0.08)
        color = white
        front = 0.06
    cs = 0.92
    width = 0.055 * cs
    stem = [(0.12, -0.22), (0.12, -0.1), (0.12, 0.02), (0.12, 0.14)]
    _asg_polyline(qlabs, obj, stem, width, 0.025, color, front=front, coord_scale=cs)
    arc = _asg_arc_points(-0.02, 0.14, 0.14, 0.0, 180.0, 22)
