def _asg_spawn_speed_limit(qlabs, obj, speed_kmh):
    red = [0.85, 0.03, 0.03]
    white = [0.96, 0.96, 0.96]
    black = [0.02, 0.02, 0.02]
    _asg_spawn_cube(qlabs, obj, 0.0, 1.5, 0.0, [0.16, 0.16, 3.0], [0.45, 0.45, 0.45], rotation=[0.0, 0.0, 0.0], roughness=0.8, collisions=True)
    _asg_spawn_disc(qlabs, obj, 2.2, red, z=3.0, front=0.0, depth=0.12)
    _asg_spawn_disc(qlabs, obj, 2.2 * 0.78, white, z=3.0, front=0.07, depth=0.066)
    segments = {'0': {'a', 'b', 'c', 'd', 'e', 'f'}, '1': {'b', 'c'}, '2': {'a', 'b', 'g', 'e', 'd'}, '3': {'a', 'b', 'c', 'd', 'g'}, '4': {'f', 'g', 'b', 'c'}, '5': {'a', 'f', 'g', 'c', 'd'}, '6': {'a', 'f', 'g', 'e', 'c', 'd'}, '7': {'a', 'b', 'c'}, '8': {'a', 'b', 'c', 'd', 'e', 'f', 'g'}, '9': {'a', 'b', 'c', 'd', 'f', 'g'}}
    number = str(int(speed_kmh))
    digit_width = 0.42
    digit_height = 0.88
    digit_gap = 0.14
    thickness = 0.095
    depth = 0.055
    total_width = len(number) * digit_width + (len(number) - 1) * digit_gap
    first = -total_width / 2.0 + digit_width / 2.0
    horizontal_length = digit_width * 0.82
    vertical_length = digit_height * 0.38
    defs = {'a': (0.0, +digit_height / 2.0, horizontal_length, thickness), 'g': (0.0, 0.0, horizontal_length, thickness), 'd': (0.0, -digit_height / 2.0, horizontal_length, thickness), 'f': (-digit_width / 2.0, +digit_height / 4.0, thickness, vertical_length), 'b': (+digit_width / 2.0, +digit_height / 4.0, thickness, vertical_length), 'e': (-digit_width / 2.0, -digit_height / 4.0, thickness, vertical_length), 'c': (+digit_width / 2.0, -digit_height / 4.0, thickness, vertical_length)}
    yaw = _asg_yaw(obj)
    for digit_index, digit in enumerate(number):
        center = first + digit_index * (digit_width + digit_gap)
        for name in segments.get(digit, set()):
            dx, dz, sx, sz = defs[name]
            location = _asg_world(obj, center + dx, 3.0 + dz, 0.13)
            _asg_spawn_shape_world(qlabs, obj, location, [0.0, 0.0, yaw + math.pi / 2.0], [sx, depth, sz], QLabsBasicShape.SHAPE_CUBE, black, roughness=0.8, collisions=False)

def _spawn_approved_catalog_sign(qlabs, obj, sign_type):
    if sign_type == 'front_or_right':
        return _asg_spawn_front_or_side(qlabs, obj, left=False)
    if sign_type == 'front_or_left':
        return _asg_spawn_front_or_side(qlabs, obj, left=True)
    if sign_type == 'right_turn':
        return _asg_spawn_turn_warning(qlabs, obj, left=False)
    if sign_type == 'left_turn':
        return _asg_spawn_turn_warning(qlabs, obj, left=True)
    if sign_type == 'u_turn':
        return _asg_spawn_u_turn(qlabs, obj, prohibited=False)
    if sign_type == 'no_u_turn':
        return _asg_spawn_u_turn(qlabs, obj, prohibited=True)
    if sign_type == 'parking':
        return _asg_spawn_parking(qlabs, obj)
    if sign_type == 'no_parking':
        return _asg_spawn_no_parking(qlabs, obj)
    if sign_type == 'no_overtaking':
        return _asg_spawn_no_overtaking(qlabs, obj)
    if sign_type == 'right_or_left':
        return _asg_spawn_right_or_left(qlabs, obj)
    if sign_type == 'pedestrian_crossing':
        return _asg_spawn_pedestrian_crossing(qlabs, obj)
    if sign_type.startswith('speed_'):
        try:
            speed = int(sign_type.split('_', 1)[1])
        except (TypeError, ValueError):
            speed = 50
        return _asg_spawn_speed_limit(qlabs, obj, speed)
    return None

def spawn_catalog_traffic_sign(qlabs, obj):
    """Spawn one Plane-validated custom traffic sign.

    Stop, Yield, and Roundabout are native QLabs actor types and are exported
    through their dedicated editor objects, not through this custom catalog.
    Unsupported legacy catalog keys are skipped instead of generating the old
    approximate fallback geometry.
    """
    sign_type = str(obj.get('sign_type', 'front_or_right'))
    if sign_type not in APPROVED_CUSTOM_SIGN_TYPES:
        print('Skipping unsupported legacy custom traffic sign: ' + sign_type)
        return None
    return _spawn_approved_catalog_sign(qlabs, obj, sign_type)

def _next_composite_basic_shape_id():
    global NEXT_COMPOSITE_BASIC_SHAPE_ACTOR_NUMBER
    actor_number = NEXT_COMPOSITE_BASIC_SHAPE_ACTOR_NUMBER
    NEXT_COMPOSITE_BASIC_SHAPE_ACTOR_NUMBER += 1
    return actor_number

def _spawn_camel_child(qlabs, root, offset, dimensions, color, shape='cube', rotation=None):
    if rotation is None:
        rotation = [0.0, 0.0, 0.0]
    config = {'cube': QLabsBasicShape.SHAPE_CUBE, 'sphere': QLabsBasicShape.SHAPE_SPHERE, 'cylinder': QLabsBasicShape.SHAPE_CYLINDER}.get(shape, QLabsBasicShape.SHAPE_CUBE)
    child = QLabsBasicShape(qlabs)
    child.spawn_id_and_parent_with_relative_transform_degrees(actorNumber=_next_composite_basic_shape_id(), location=list(offset), rotation=list(rotation), scale=list(dimensions), configuration=config, parentClassID=QLabsBasicShape.ID_BASIC_SHAPE, parentActorNumber=root.actorNumber, parentComponent=0, waitForConfirmation=True)
    child.set_material_properties(color=list(color), roughness=0.82, metallic=False, waitForConfirmation=True)
    child.set_enable_dynamics(False, waitForConfirmation=True)
    return child

def spawn_camel(qlabs, obj):
    """Spawn a low-poly camel rig using addressable BasicShape actors.

    QLabsAnimal documents Goat, Sheep, and Cow only, so a camel is constructed
    from QLabs-provided BasicShapes and parented to one movable root.
    """
    scale = actor_effective_scale(obj)
    yaw = editor_yaw_to_qlabs_radians(obj.get('rotation_deg', 0.0))
    root = QLabsBasicShape(qlabs)
    root.spawn_id(actorNumber=_next_composite_basic_shape_id(), location=actor_location(obj), rotation=[0.0, 0.0, yaw], scale=[1.0, 1.0, 1.0], configuration=QLabsBasicShape.SHAPE_CUBE, waitForConfirmation=True)
    root.set_material_properties(color=[0.73, 0.48, 0.24], roughness=0.9, metallic=False, waitForConfirmation=True)
    root.set_enable_collisions(False, waitForConfirmation=True)
    root.set_enable_dynamics(False, waitForConfirmation=True)
    tan = [0.73, 0.48, 0.24]
    dark = [0.38, 0.23, 0.12]
    _spawn_camel_child(qlabs, root, [0.0, 0.0, 1.35 * scale], [2.25 * scale, 0.78 * scale, 1.05 * scale], tan, 'sphere')
    _spawn_camel_child(qlabs, root, [-0.48 * scale, 0.0, 2.03 * scale], [0.82 * scale, 0.72 * scale, 0.9 * scale], tan, 'sphere')
    _spawn_camel_child(qlabs, root, [0.42 * scale, 0.0, 2.02 * scale], [0.8 * scale, 0.7 * scale, 0.86 * scale], tan, 'sphere')
    _spawn_camel_child(qlabs, root, [1.16 * scale, 0.0, 2.02 * scale], [0.36 * scale, 0.42 * scale, 1.55 * scale], tan, 'cube', [0.0, 22.0, 0.0])
    _spawn_camel_child(qlabs, root, [1.55 * scale, 0.0, 2.7 * scale], [0.72 * scale, 0.48 * scale, 0.48 * scale], tan, 'sphere')
    for lx in (-0.7, 0.7):
        for ly in (-0.25, 0.25):
            _spawn_camel_child(qlabs, root, [lx * scale, ly * scale, 0.55 * scale], [0.2 * scale, 0.2 * scale, 1.1 * scale], tan, 'cube')
            _spawn_camel_child(qlabs, root, [lx * scale + 0.08 * scale, ly * scale, 0.08 * scale], [0.42 * scale, 0.28 * scale, 0.14 * scale], dark, 'cube')
    _spawn_camel_child(qlabs, root, [-1.18 * scale, 0.0, 1.42 * scale], [0.1 * scale, 0.1 * scale, 0.85 * scale], dark, 'cube', [0.0, -35.0, 0.0])
    return root

def spawn_scene_actor(qlabs, obj):
    global NEXT_SECONDARY_QCAR_ACTOR_NUMBER
    obj_type = str(obj.get('type', ''))
    yaw = editor_yaw_to_qlabs_radians(obj.get('rotation_deg', 0.0))
    actor_scale = actor_effective_scale(obj)
    uniform_scale = [actor_scale, actor_scale, actor_scale]
    configuration = int(obj.get('configuration', 0))
    if obj_type == 'stop_sign':
        actor = QLabsStopSign(qlabs)
        actor.spawn(location=actor_location(obj), rotation=[0, 0, yaw], scale=uniform_scale, configuration=0, waitForConfirmation=True)
        return actor
    if obj_type == 'yield_sign':
        actor = QLabsYieldSign(qlabs)
        actor.spawn(location=actor_location(obj), rotation=[0, 0, yaw], scale=uniform_scale, configuration=0, waitForConfirmation=True)
        return actor
    if obj_type == 'roundabout_sign':
        actor = QLabsRoundaboutSign(qlabs)
        actor.spawn(location=actor_location(obj), rotation=[0, 0, yaw], scale=uniform_scale, configuration=0, waitForConfirmation=True)
        return actor
    if obj_type == 'traffic_sign_catalog':
        return spawn_catalog_traffic_sign(qlabs, obj)
    if obj_type == 'animal':
        animal_type = str(obj.get('animal_type', 'goat'))
        if animal_type == 'camel':
            return spawn_camel(qlabs, obj)
        actor = QLabsAnimal(qlabs)
        config_map = {'goat': actor.GOAT, 'sheep': actor.SHEEP, 'cow': actor.COW}
        actor.spawn(location=actor_location(obj), rotation=[0, 0, yaw], scale=uniform_scale, configuration=config_map.get(animal_type, actor.GOAT), waitForConfirmation=True)
        return actor
    return None

def spawn_scene_actors(qlabs, objects):
    scene_types = {'animal', 'roundabout_sign', 'stop_sign', 'traffic_sign_catalog', 'yield_sign'}
    for obj in objects:
        obj_type = obj.get('type')
        if obj_type not in scene_types:
            continue
        if obj_type in {'person', 'animal', 'secondary_qcar2'} and str(obj.get('spawn_mode', 'immediate')) == 'triggered':
            continue
        actor = spawn_scene_actor(qlabs, obj)
        object_id = str(obj.get('id', ''))
        if actor is not None and object_id:
            _register_actor_handle(obj, actor)

def main():
    print('Connecting to QLabs...')
    qlabs = QuanserInteractiveLabs()
    if not qlabs.open('localhost'):
        print('Unable to connect to QLabs.')
        print('Open QLabs in the Plane / selected custom workspace workspace and try again.')
        sys.exit(1)
    print('Connected to QLabs.')
    qlabs.destroy_all_spawned_actors()
    objects = TRACK_DATA.get('objects', [])
    spawn_scene_actors(qlabs, objects)
    print('QLabs track created. Project scale = ' + str(TRACK_DATA.get('project', {}).get('scale_name', '1:1')))
if __name__ == '__main__':
    main()
